using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json.Linq;
public static class BNRepair {
 static string R=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));
 public static object Links(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying)throw new Exception("Saved edit required");var root=GameObject.Find("B2_DomeServiceNetwork").transform.Find("DomeMezzanines");int count=0;foreach(string id in new[]{"E01","E02","W02","C02"}){var parent=root.Cast<Transform>().Single(t=>t.name.StartsWith("B2_"+id+"_"));string name="B2_"+id+"_ContinuousHeaderLinks";if(parent.Find(name))continue;var src=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Afrer_Seconds/05.Model/Environment/B2/BN_"+id+"_HeaderLinks.fbx");if(!src)throw new Exception("Missing header asset");var g=(GameObject)PrefabUtility.InstantiatePrefab(src,parent);g.name=name;g.transform.localPosition=Vector3.zero;g.transform.localRotation=Quaternion.identity;foreach(var f in g.GetComponentsInChildren<MeshFilter>())f.gameObject.AddComponent<MeshCollider>().sharedMesh=f.sharedMesh;PrefabUtility.RecordPrefabInstancePropertyModifications(g.transform);PrefabUtility.RecordPrefabInstancePropertyModifications(g);count++;}Physics.SyncTransforms();EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);return new{connectedDomeHeaders=count};}
 public static object Diagnose(){var g=new GameObject("BN_Probe"){hideFlags=HideFlags.HideAndDontSave};var cc=g.AddComponent<CapsuleCollider>();cc.radius=.28f;cc.height=1.77f;cc.center=Vector3.up*.935f;g.transform.position=new Vector3(121.8f,-30.4f,8.099844f);var col=GameObject.Find("B2_E02_RingWalkCollision").GetComponent<MeshCollider>();var passed=Physics.ComputePenetration(cc,g.transform.position,Quaternion.identity,col,col.transform.position,col.transform.rotation,out var dir,out float d);UnityEngine.Object.DestroyImmediate(g);return new{passed,d,direction=dir.ToString()};}
 public static object MoveProps(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying)throw new Exception("Saved edit required");string file=R+"/SourceAssets/B2_DomeNetwork/layout.json";var data=JObject.Parse(File.ReadAllText(file));var changes=new[]{new{name="B2_W02_Dense_039_MotorSpares",yaw=-60f},new{name="B2_E01_Dense_058_ToolTrolley",yaw=180f}};foreach(var c in changes){var g=GameObject.Find(c.name);g.transform.localRotation=Quaternion.Euler(0,c.yaw,0);var p=data["placements"].Single(v=>(string)v["name"]==c.name);p["yaw"]=c.yaw;PrefabUtility.RecordPrefabInstancePropertyModifications(g.transform);}File.WriteAllText(file,data.ToString());Physics.SyncTransforms();EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);return changes;}
}
